// 1. Recursive Variadic Function and Base Case

void print_all() {}

template<typename T, typename... Args>
void print_all(T head, Args... tail) {
    // std::cout << head << '\n';
    print_all(tail...); // Pack expansion in function call
}


// 2. C++17 Fold Expressions (Binary Right Fold)

template<typename... Nums>
auto sum_all(Nums... args) {
    // (A op ... op B)
    return (args + ...); // Requires C++17
}

template<typename... Items>
void call_void_functions(Items... funcs) {
    // Uses comma operator to guarantee sequential execution
    (funcs(), ...);
}


// 3. Pack Expansion in Initializer Lists (Applying Transformation)

template<typename T, typename... Args>
std::vector<T> make_vec(Args... args) {
    // Expands the expression `T{args}` for every element
    return { T{args}... };
}


// 4. Variadic Class Template Definition

template<typename... Types>
class DataStore {};

// Partial specialization (recursive definition pattern)
template<typename Head, typename... Tail>
class DataStore<Head, Tail...> : public DataStore<Tail...> {
    Head value;
};

// Base case specialization
template<>
class DataStore<> {};
